CREATE TABLE IF NOT EXISTS sales_invoices (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches(id), warehouse_id uuid REFERENCES warehouses(id), party_id uuid REFERENCES parties(id), salesman_id uuid, kind text NOT NULL DEFAULT 'sale', status text NOT NULL DEFAULT 'draft', number text, currency text NOT NULL DEFAULT 'SAR', price_includes_vat boolean NOT NULL DEFAULT false, cash_customer_name text, cash_customer_mobile text, invoice_discount numeric(20,4) NOT NULL DEFAULT 0, extra_tax numeric(20,4) NOT NULL DEFAULT 0, withholding numeric(20,4) NOT NULL DEFAULT 0, subtotal numeric(20,4) NOT NULL DEFAULT 0, tax_total numeric(20,4) NOT NULL DEFAULT 0, total numeric(20,4) NOT NULL DEFAULT 0, paid_total numeric(20,4) NOT NULL DEFAULT 0, payment_status text NOT NULL DEFAULT 'unpaid', cost_total numeric(20,4) NOT NULL DEFAULT 0, profit numeric(20,4) NOT NULL DEFAULT 0, zatca_uuid uuid, zatca_hash text, zatca_qr text, zatca_status text, posted_at timestamptz, voided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS sales_invoices_tenant_number_key ON sales_invoices(tenant_id, number) WHERE number IS NOT NULL;
CREATE INDEX IF NOT EXISTS sales_invoices_scope_idx ON sales_invoices(tenant_id, branch_id, status);
CREATE INDEX IF NOT EXISTS sales_invoices_party_idx ON sales_invoices(tenant_id, party_id);
CREATE TABLE IF NOT EXISTS sales_invoice_lines (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, invoice_id uuid NOT NULL REFERENCES sales_invoices(id) ON DELETE CASCADE, line_no int NOT NULL, item_id uuid REFERENCES items(id), tax_group_id uuid REFERENCES tax_groups(id), description text, quantity numeric(20,4) NOT NULL CHECK (quantity > 0), unit_price numeric(20,4) NOT NULL CHECK (unit_price >= 0), discount_rate numeric(20,4) NOT NULL DEFAULT 0, discount_amount numeric(20,4) NOT NULL DEFAULT 0, tax_rate numeric(20,4) NOT NULL DEFAULT 0, net numeric(20,4) NOT NULL DEFAULT 0, tax numeric(20,4) NOT NULL DEFAULT 0, total numeric(20,4) NOT NULL DEFAULT 0, cost_total numeric(20,4) NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS sales_invoice_lines_invoice_line_key ON sales_invoice_lines(invoice_id, line_no);
CREATE INDEX IF NOT EXISTS sales_invoice_lines_scope_idx ON sales_invoice_lines(tenant_id, item_id);
CREATE TABLE IF NOT EXISTS invoice_payments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, invoice_id uuid NOT NULL REFERENCES sales_invoices(id) ON DELETE CASCADE, method text NOT NULL, amount numeric(20,4) NOT NULL CHECK (amount > 0), cash_location_id uuid, reference text, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid);
CREATE UNIQUE INDEX IF NOT EXISTS invoice_payments_tenant_idempotency_key ON invoice_payments(tenant_id, idempotency_key);
CREATE INDEX IF NOT EXISTS invoice_payments_invoice_idx ON invoice_payments(tenant_id, invoice_id);
CREATE TABLE IF NOT EXISTS sales_adjustment_notes (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, invoice_id uuid REFERENCES sales_invoices(id), branch_id uuid NOT NULL REFERENCES branches(id), kind text NOT NULL, status text NOT NULL DEFAULT 'draft', number text, reason text NOT NULL, amount numeric(20,4) NOT NULL CHECK (amount > 0), posted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS sales_adjustment_notes_tenant_number_key ON sales_adjustment_notes(tenant_id, number) WHERE number IS NOT NULL;
CREATE TABLE IF NOT EXISTS offers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, status text NOT NULL DEFAULT 'active', target_type text NOT NULL DEFAULT 'quantity', target_value numeric(20,4) NOT NULL DEFAULT 0, discount_type text NOT NULL DEFAULT 'percent', discount_value numeric(20,4) NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS offers_tenant_code_key ON offers(tenant_id, code);
CREATE INDEX IF NOT EXISTS offers_validity_idx ON offers(tenant_id, valid_from, valid_to);
CREATE TABLE IF NOT EXISTS offer_items (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, offer_id uuid NOT NULL REFERENCES offers(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, PRIMARY KEY (tenant_id, offer_id, item_id));
CREATE TABLE IF NOT EXISTS offer_parties (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, offer_id uuid NOT NULL REFERENCES offers(id) ON DELETE CASCADE, party_id uuid NOT NULL REFERENCES parties(id), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, PRIMARY KEY (tenant_id, offer_id, party_id));
CREATE TABLE IF NOT EXISTS salesmen (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name text NOT NULL, employee_ref text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS salesmen_tenant_name_key ON salesmen(tenant_id, name);

ALTER TABLE sales_invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE sales_invoice_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoice_payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE sales_adjustment_notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE offers ENABLE ROW LEVEL SECURITY;
ALTER TABLE offer_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE offer_parties ENABLE ROW LEVEL SECURITY;
ALTER TABLE salesmen ENABLE ROW LEVEL SECURITY;

DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['sales_invoices','sales_invoice_lines','invoice_payments','sales_adjustment_notes','offers','offer_items','offer_parties','salesmen'] LOOP EXECUTE format('DROP POLICY IF EXISTS ' || table_name || '_tenant_isolation ON ' || table_name); EXECUTE format('CREATE POLICY ' || table_name || '_tenant_isolation ON ' || table_name || ' USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)'); END LOOP; END $$;
